//! Module: lightning.guest_vulkan.generate_d3d11_commands_header
//! Purpose: Generate the native command journal ABI from its Rust authority.
//! Created: 2026-11-07
//! Architecture: Build-time header generation; no VM or device operations.

mod d3d11_commands;

fn main() {
    print!(
        "/* Generated by generate_d3d11_commands_header.rs. */\n\
#ifndef QLG_COMMAND_JOURNAL_H\n#define QLG_COMMAND_JOURNAL_H\n\
#include <stddef.h>\n#include <stdint.h>\n\
#define QLG_COMMAND_MAX_ARGS {}\n",
        d3d11_commands::MAX_ARGUMENTS
    );
    println!(
        "#define QLG_COMMAND_MAX_PACKET_BYTES {}",
        d3d11_commands::MAX_PACKET_BYTES
    );
    print!(
        "{}",
        r#"
struct QlgCommandJournal;
struct QlgCommandRegion { const uint8_t *data; size_t bytes; };
typedef int (*QlgCommandInvoke)(uintptr_t, const uint64_t *, const QlgCommandRegion *);
typedef void (*QlgCommandTransform)(uint8_t *, const uint8_t *, size_t);
struct QlgCommandInput { const uint8_t *data; size_t bytes; QlgCommandTransform transform; };
extern "C" {
QlgCommandJournal *qlg_commands_new(uintptr_t owner);
int qlg_commands_append(QlgCommandJournal *, QlgCommandInvoke, const uint64_t *, size_t, const QlgCommandInput *);
int qlg_commands_map(QlgCommandJournal *, uintptr_t key, uint32_t subresource, size_t bytes,
                     int discard, QlgCommandInvoke, const uint64_t *, size_t, uint8_t **);
int qlg_commands_unmap(QlgCommandJournal *, uintptr_t key, uint32_t subresource);
int qlg_commands_seal(QlgCommandJournal *);
int qlg_commands_execute(const QlgCommandJournal *, uintptr_t owner);
void qlg_commands_destroy(QlgCommandJournal *);
}
#endif
"#
    );
}
